<?php
declare(strict_types=1);
namespace App\Services;
use App\Support\Database;
final class CountryAdminService {public function __construct(private ?Database $db){}public function update(int $id,array $data):void{if(!$this->db)throw new \RuntimeException('Database unavailable.');$allowed=['name','local_name','currency_code','currency_symbol','currency_symbol_position','locale','timezone','default_language_id','sort_order'];$sets=[];$values=[];foreach($allowed as$f)if(array_key_exists($f,$data)){$sets[]="$f=?";$values[]=$data[$f];}$values[]=$id;$this->db->execute('UPDATE countries SET '.implode(',',$sets).',updated_at=NOW() WHERE id=?',$values);}public function enabled(int $id,bool $enabled):void{$country=app('countries')->byId($id);if(($country['is_global']??false)&&!$enabled)throw new \DomainException('Global must remain enabled because it is the fallback Country Pack.');$this->db?->execute('UPDATE countries SET is_enabled=?,updated_at=NOW() WHERE id=?',[$enabled?1:0,$id]);if($country)app('countries')->forget($country);}public function theme(int $id,array $theme):void{$safe=app('theme')->sanitize($theme);$this->db?->execute('UPDATE countries SET theme=?,updated_at=NOW() WHERE id=?',[json_encode($safe,JSON_THROW_ON_ERROR),$id]);if($country=app('countries')->byId($id))app('countries')->forget($country);}public function attachAsset(int $countryId,string $type,array $file,string $alt=''):int{if(!in_array($type,['logo','dark_logo','favicon','hero','secondary_banner','about','investment','trust','contact'],true))throw new \InvalidArgumentException('Invalid image slot.');$name=app('upload')->store($file,false,true);$this->db?->execute('INSERT INTO country_assets (country_id,asset_type,storage_path,alt_text,is_active,created_at,updated_at) VALUES (?,?,?,?,1,NOW(),NOW())',[$countryId,$type,$name,$alt?:null]);$id=(int)$this->db?->pdo()->lastInsertId();if(in_array($type,['logo','dark_logo','favicon'],true))app('branding')->attachAsset($countryId,$type.'_asset_id',$id);return$id;}public function asset(int $id):?array{return $this->db?->one('SELECT * FROM country_assets WHERE id=? AND is_active=1',[$id]);}}
